<script module lang="ts">
/**
 * Single-value choice from a closed list (`design/components/select.md`).
 *
 * Generated by `pnpm shells` from `packages/shells/src/members/select.ts`, the member's
 * framework-neutral description. Never edit it by hand: change the description and
 * run `pnpm shells`.
 */
import { onDestroy } from 'svelte'

import * as zag from '@zag-js/select'
import { useMachine } from '@zag-js/svelte'

import {
  Icon,
  Portal,
  agentMember,
  attributes,
  followHighlight,
  joinSlot,
  mergeParts,
  normalizeProps,
  returnFocus,
  useDirection,
  useMediaQuery,
  watchEffect,
} from '@polymorph/svelte'
import { usePresence } from '@polymorph/svelte/motion'
import styles from '@polymorph/recipes/controls/select.module.css'
import sheet from '@polymorph/recipes/overlays/sheet.module.css'

export interface SelectOption {
  value: string
  label: string
  description?: string
  disabled?: boolean
}

export interface SelectOptionGroup {
  label: string
  options: SelectOption[]
}

export interface SelectProps {
  'aria-describedby'?: string
  /**
   * Wired by FormField; set directly only when there is no visible label.
   */
  'aria-label'?: string
  /**
   * Names the field from a label elsewhere on the page, such as `SettingsRow`'s row label, which
   * is one label for a whole row rather than one per control.
   */
  'aria-labelledby'?: string
  'aria-required'?: boolean
  /**
   * Opens on mount. For galleries and tests; screens let the user open it.
   */
  defaultOpen?: boolean
  defaultValue?: string | null
  disabled?: boolean
  /**
   * Labels a selectable empty choice, always rendered as the **first** item. Choosing it reports
   * `null`. The trigger then shows this label as a real value, because "All" is a chosen state,
   * not a missing value.
   */
  emptyOption?: string
  id?: string
  invalid?: boolean
  name?: string
  onChange?: (value: string | null) => void
  /**
   * Flat, grouped, or mixed. `emptyOption` stays first and belongs to no group.
   */
  options: (SelectOption | SelectOptionGroup)[]
  /**
   * Muted, and shown only until there is a value. Cannot be combined with `emptyOption`.
   */
  placeholder?: string
  /**
   * `'auto'` shows the panel as a sheet below `30rem` (the conventions' sheet presentation, the
   * usual phone pattern for choosing from a list). `'popover'` keeps the popper at every width,
   * for the rare pointer-first case that needs precision. There is no always-sheet value,
   * because a bottom sheet on a wide pointer screen is the wrong pattern (`docs/layout.md`).
   */
  presentation?: 'auto' | 'popover'
  size?: 'sm' | 'md' | 'lg'
  /**
   * `null` is the empty choice, which is allowed only when `emptyOption` is set.
   */
  value?: string | null
}
</script>

<script lang="ts">
let {
  'aria-describedby': ariaDescribedbyOwn,
  'aria-label': ariaLabel,
  'aria-labelledby': ariaLabelledbyOwn,
  'aria-required': ariaRequiredOwn,
  defaultOpen,
  defaultValue,
  disabled = false,
  emptyOption,
  id: idOwn,
  invalid: invalidOwn = false,
  name,
  onChange,
  options,
  placeholder,
  presentation = 'auto',
  size = 'md',
  value,
}: SelectProps = $props()
const uid = $props.id()
const joined = joinSlot(undefined, () => ({ disabled: disabled, name: name, size: size }))
const ariaDescribedby = $derived(
  joined.passed['aria-describedby'] === undefined
    ? ariaDescribedbyOwn
    : (joined.passed['aria-describedby'] as typeof ariaDescribedbyOwn),
)
const ariaLabelledby = $derived(
  joined.passed['aria-labelledby'] === undefined
    ? ariaLabelledbyOwn
    : (joined.passed['aria-labelledby'] as typeof ariaLabelledbyOwn),
)
const ariaRequired = $derived(
  joined.passed['aria-required'] === undefined
    ? ariaRequiredOwn
    : (joined.passed['aria-required'] as typeof ariaRequiredOwn),
)
const id = $derived(
  joined.passed['id'] === undefined ? idOwn : (joined.passed['id'] as typeof idOwn),
)
const invalid = $derived(
  joined.passed['invalid'] === undefined
    ? invalidOwn
    : (joined.passed['invalid'] as typeof invalidOwn),
)
let panel = $state<HTMLElement | null>(null)
let scrim = $state<HTMLElement | null>(null)
let sheetPanel = $state<HTMLElement | null>(null)
let trigger = $state<HTMLElement | null>(null)
const phone = useMediaQuery('phone')
const sheeting = $derived(presentation === 'auto' && phone.current)
const emptyChoice = $derived({
  value: '__polymorph-empty-choice__',
  label: emptyOption ?? '',
  description: undefined,
  disabled: false,
})
const flat = $derived([
  ...(emptyOption === undefined ? [] : [emptyChoice]),
  ...options.flatMap((entry) => ('options' in entry ? entry.options : [entry])),
])
const documentDirection = useDirection()
const service = useMachine(
  zag.machine,
  () =>
    ({
      id: uid,
      dir: documentDirection.current,
      collection: zag.collection({
        items: flat,
        itemToValue: (item) => item.value,
        itemToString: (item) => item.label,
        isItemDisabled: (item) => item.disabled === true,
      }),
      value:
        value === undefined
          ? undefined
          : value === null
            ? emptyOption === undefined
              ? []
              : ['__polymorph-empty-choice__']
            : [value],
      defaultValue:
        defaultValue === undefined && emptyOption !== undefined
          ? ['__polymorph-empty-choice__']
          : defaultValue === undefined
            ? undefined
            : defaultValue === null
              ? emptyOption === undefined
                ? []
                : ['__polymorph-empty-choice__']
              : [defaultValue],
      defaultOpen: defaultOpen,
      disabled: disabled,
      invalid: invalid,
      positioning: { placement: 'bottom-start' as const, gutter: 2 },
      ids: id === undefined ? undefined : { trigger: id },
      onValueChange: (details) => {
        onChange?.(
          details.value[0] === undefined || details.value[0] === '__polymorph-empty-choice__'
            ? null
            : details.value[0],
        )
      },
    }) as Partial<zag.Props>,
)
const api = $derived(zag.connect(service, normalizeProps))
const shown = $derived(flat.find((choice) => api.value.includes(choice.value)))
const placeholderShown = $derived(shown === undefined)
const present = usePresence(
  () => api.open && !sheeting,
  () => panel,
)
const sheetPresent = usePresence(
  () => api.open && sheeting,
  () => sheetPanel,
  'sheet.panel',
  { sheetSide: 'bottom' },
)
const scrimPresent = usePresence(
  () => api.open && sheeting,
  () => scrim,
  'dialog.scrim',
)
const effect1 = () => {
  api.open &&
    api.highlightedValue === null &&
    api.setHighlightValue(api.value[0] ?? flat.find((choice) => !choice.disabled)?.value ?? '')
}
watchEffect(effect1, { watch: () => api.open })
const effect2 = () => {
  api.open || returnFocus(trigger, panel)
}
watchEffect(effect2, { watch: () => api.open, mount: false })
const effect3 = () => {
  followHighlight(panel, api.highlightedValue)
}
watchEffect(effect3, { watch: () => api.highlightedValue })
let release4: (() => void) | undefined
const effect4 = () => {
  release4?.()
  const ran = agentMember({
    member: 'Select',
    element: () => trigger,
    state: () => ({
      value:
        api.value[0] === undefined
          ? emptyOption === undefined
            ? null
            : ''
          : api.value[0] === '__polymorph-empty-choice__'
            ? ''
            : api.value[0],
      options: flat.map((choice) => ({
        id: choice.value === '__polymorph-empty-choice__' ? '' : choice.value,
        label: choice.label,
        ...(choice.disabled === true ? { disabled: true } : {}),
      })),
      open: api.open,
      disabled: disabled,
    }),
    actions: {
      choose: {
        argument: 'id',
        run: (value) => api.setValue([value === '' ? '__polymorph-empty-choice__' : value]),
      },
      open: () => api.setOpen(true),
      close: () => api.setOpen(false),
    },
  })
  release4 = () => {
    ran()
  }
}
watchEffect(effect4)
onDestroy(() => release4?.())
</script>

{@render joined.start?.()
}{#if joined.shown
  }<button
    bind:this={trigger}
    {...attributes(api.getTriggerProps())}
    class={styles.trigger}
    aria-label={ariaLabel}
    aria-labelledby={ariaLabelledby}
    aria-describedby={ariaDescribedby}
    aria-required={ariaRequired}
    aria-invalid={(invalid) ? true : undefined}
    data-size={size}
    data-invalid={(invalid) ? '' : undefined}
    data-disabled={(disabled) ? '' : undefined}
    data-placeholder={(placeholderShown) ? '' : undefined}
    data-member="select"
    ><span class={styles.value}
      >{shown?.label ?? (emptyOption === undefined ? (placeholder ?? '') : '')
    }</span
    ><span class={styles.chevron} aria-hidden="true"><Icon name="expand" {size} /></span
  ></button
  >{#if name !== undefined
    }<input
      type="hidden"
      {name}
      value={api.value[0] === undefined || api.value[0] === '__polymorph-empty-choice__' ? '' : api.value[0]}
      disabled={disabled || undefined}
  />{/if
  }<Portal
    >{#if present.current
      }<div {...attributes(api.getPositionerProps())}
        ><div
          bind:this={panel}
          {...attributes(mergeParts(api.getContentProps(), { onFocus: () => { followHighlight(panel, api.highlightedValue) } }))}
          class={styles.content}
          style:--radix-select-trigger-width={'var(--reference-width)'}
          style:--radix-select-content-available-height={'var(--available-height)'}
          style:--radix-select-content-transform-origin={'var(--transform-origin)'}
          hidden={undefined}
          data-size={size}
          data-member="select"
          ><div class={styles.viewport}
            >{#if emptyOption !== undefined
              }<div
                {...attributes(mergeParts(api.getItemProps({ item: emptyChoice }), { onFocus: () => { api.setHighlightValue(emptyChoice.value) } }))}
                class={styles.item}
                tabindex="-1"
                ><span class={styles.check}
                  >{#if api.value.includes(emptyChoice.value)}<Icon name="confirm" size="sm" />{/if
                }</span
                ><span class={styles.text}
                  ><span>{emptyChoice.label}</span
                  >{#if emptyChoice.description !== undefined
                    }<span class={styles.description}>{emptyChoice.description}</span
                  >{/if
                }</span
              ></div
            >{/if
            }{#each options as entry ('options' in entry ? `group-${entry.label}` : entry.value)
              }{#if 'options' in entry
                }<div
                  {...attributes(api.getItemGroupProps({ id: entry.label }))}
                  class={styles.group}
                  ><div
                    {...attributes(api.getItemGroupLabelProps({ htmlFor: entry.label }))}
                    class={styles.groupLabel}
                    >{entry.label
                  }</div
                  >{#each entry.options as choice (choice.value)
                    }<div
                      {...attributes(mergeParts(api.getItemProps({ item: choice }), { onFocus: () => { api.setHighlightValue(choice.value) } }))}
                      class={styles.item}
                      tabindex="-1"
                      ><span class={styles.check}
                        >{#if api.value.includes(choice.value)}<Icon name="confirm" size="sm" />{/if
                      }</span
                      ><span class={styles.text}
                        ><span>{choice.label}</span
                        >{#if choice.description !== undefined
                          }<span class={styles.description}>{choice.description}</span
                        >{/if
                      }</span
                    ></div
                  >{/each
                }</div
              >{:else
                }<div
                  {...attributes(mergeParts(api.getItemProps({ item: entry }), { onFocus: () => { api.setHighlightValue(entry.value) } }))}
                  class={styles.item}
                  tabindex="-1"
                  ><span class={styles.check}
                    >{#if api.value.includes(entry.value)}<Icon name="confirm" size="sm" />{/if
                  }</span
                  ><span class={styles.text}
                    ><span>{entry.label}</span
                    >{#if entry.description !== undefined
                      }<span class={styles.description}>{entry.description}</span
                    >{/if
                  }</span
                ></div
              >{/if
            }{/each
          }</div
        ></div
      ></div
    >{/if
    }{#if scrimPresent.current
      }<div bind:this={scrim} class={sheet.scrim} data-state={api.open ? 'open' : 'closed'}></div
    >{/if
    }{#if sheetPresent.current
      }<div class={sheet.positioner}
        ><div
          bind:this={sheetPanel}
          class={sheet.panel}
          data-presentation="sheet"
          data-state={api.open ? 'open' : 'closed'}
          tabindex="-1"
          ><div
            bind:this={panel}
            {...attributes(mergeParts(api.getContentProps(), { onFocus: () => { followHighlight(panel, api.highlightedValue) } }))}
            class={styles.sheetList}
            hidden={undefined}
            data-size={size}
            data-member="select"
            >{#if emptyOption !== undefined
              }<div
                {...attributes(mergeParts(api.getItemProps({ item: emptyChoice }), { onFocus: () => { api.setHighlightValue(emptyChoice.value) } }))}
                class={styles.item}
                tabindex="-1"
                ><span class={styles.check}
                  >{#if api.value.includes(emptyChoice.value)}<Icon name="confirm" size="sm" />{/if
                }</span
                ><span class={styles.text}
                  ><span>{emptyChoice.label}</span
                  >{#if emptyChoice.description !== undefined
                    }<span class={styles.description}>{emptyChoice.description}</span
                  >{/if
                }</span
              ></div
            >{/if
            }{#each options as entry ('options' in entry ? `group-${entry.label}` : entry.value)
              }{#if 'options' in entry
                }<div
                  {...attributes(api.getItemGroupProps({ id: entry.label }))}
                  class={styles.group}
                  ><div
                    {...attributes(api.getItemGroupLabelProps({ htmlFor: entry.label }))}
                    class={styles.groupLabel}
                    >{entry.label
                  }</div
                  >{#each entry.options as choice (choice.value)
                    }<div
                      {...attributes(mergeParts(api.getItemProps({ item: choice }), { onFocus: () => { api.setHighlightValue(choice.value) } }))}
                      class={styles.item}
                      tabindex="-1"
                      ><span class={styles.check}
                        >{#if api.value.includes(choice.value)}<Icon name="confirm" size="sm" />{/if
                      }</span
                      ><span class={styles.text}
                        ><span>{choice.label}</span
                        >{#if choice.description !== undefined
                          }<span class={styles.description}>{choice.description}</span
                        >{/if
                      }</span
                    ></div
                  >{/each
                }</div
              >{:else
                }<div
                  {...attributes(mergeParts(api.getItemProps({ item: entry }), { onFocus: () => { api.setHighlightValue(entry.value) } }))}
                  class={styles.item}
                  tabindex="-1"
                  ><span class={styles.check}
                    >{#if api.value.includes(entry.value)}<Icon name="confirm" size="sm" />{/if
                  }</span
                  ><span class={styles.text}
                    ><span>{entry.label}</span
                    >{#if entry.description !== undefined
                      }<span class={styles.description}>{entry.description}</span
                    >{/if
                  }</span
                ></div
              >{/if
            }{/each
          }</div
        ></div
      ></div
    >{/if
  }</Portal
>{/if
}{@render joined.end?.()}
